import{_ as e,o as a,c as t,a0 as i}from"./chunks/framework.DhQjJcnt.js";const g=JSON.parse('{"title":"Quickstart","description":"","frontmatter":{},"headers":[],"relativePath":"en/quickstart.md","filePath":"en/quickstart.md","lastUpdated":1787985369000}'),n={name:"en/quickstart.md"};function l(p,s,o,h,r,d){return a(),t("div",null,[...s[0]||(s[0]=[i(`<h1 id="quickstart" tabindex="-1">Quickstart <a class="header-anchor" href="#quickstart" aria-label="Permalink to &quot;Quickstart&quot;">​</a></h1><p>From binary to your first tunnel in about five minutes. You need three things:</p><ol><li>A server with a public IP (any VPS)</li><li>The host computer (the one running the game/service)</li><li>The guest computer (a friend&#39;s machine)</li></ol><h2 id="step-1-deploy-the-signaling-server" tabindex="-1">Step 1: Deploy the signaling server <a class="header-anchor" href="#step-1-deploy-the-signaling-server" aria-label="Permalink to &quot;Step 1: Deploy the signaling server&quot;">​</a></h2><p>On the public server:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Build (slow the first time)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Start the signaling server</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./target/release/frp-sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --addr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 0.0.0.0:8080</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --relay-addr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 0.0.0.0:8081</span></span></code></pre></div><p>Three services come up together:</p><ul><li><strong>HTTP REST</strong> (8080/tcp): room registration and lookup</li><li><strong>UDP public probe</strong> (8080/udp): clients learn their public address</li><li><strong>TCP relay</strong> (8081/tcp): data forwarding when punching fails</li></ul><blockquote><p>Open <code>8080/tcp</code>, <code>8080/udp</code>, and <code>8081/tcp</code> in both the cloud security group and the OS firewall.</p></blockquote><p>For a permanent setup see <a href="./server">Deploy the Server</a>.</p><h2 id="step-2-configure-the-client" tabindex="-1">Step 2: Configure the client <a class="header-anchor" href="#step-2-configure-the-client" aria-label="Permalink to &quot;Step 2: Configure the client&quot;">​</a></h2><p>Both host and guest need a config pointing at that server (the built-in default targets <code>127.0.0.1</code> for local testing only):</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># config/server.toml</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">signaling_addr = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://YOUR-SERVER-IP:8080&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # HTTP signaling</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">relay_addr     = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;YOUR-SERVER-IP:8081&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # TCP relay</span></span></code></pre></div><p>Use it with <code>--config</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">frp-sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config/server.toml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> game</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span></span></code></pre></div><h2 id="step-3-host-creates-a-room" tabindex="-1">Step 3: Host creates a room <a class="header-anchor" href="#step-3-host-creates-a-room" aria-label="Permalink to &quot;Step 3: Host creates a room&quot;">​</a></h2><p>On the machine running the game/service:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">frp-sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> game</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 127.0.0.1:25565</span></span></code></pre></div><p><code>--service</code> is the host&#39;s local service address (default <code>127.0.0.1:25565</code>, the Minecraft default port; use <code>--service</code> to change it). Example output:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  Room created : game-a3f9c2</span></span>
<span class="line"><span>  Signaling    : http://YOUR-SERVER-IP:8080</span></span>
<span class="line"><span>  Your ID      : 123e4567-e89b-12d3-a456-426614174000</span></span>
<span class="line"><span>  Local service: 127.0.0.1:25565</span></span>
<span class="line"><span>  Waiting for a guest to join ...</span></span></code></pre></div><p>Send <strong><code>game-a3f9c2</code></strong> to your friend.</p><h2 id="step-4-guest-joins" tabindex="-1">Step 4: Guest joins <a class="header-anchor" href="#step-4-guest-joins" aria-label="Permalink to &quot;Step 4: Guest joins&quot;">​</a></h2><p>On the friend&#39;s machine:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">frp-sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> game</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> join</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> game-a3f9c2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --listen</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 127.0.0.1:25565</span></span></code></pre></div><p><code>--listen</code> is the local port the guest listens on (default <code>127.0.0.1:25565</code>). Example output:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  Joined room : game-a3f9c2</span></span>
<span class="line"><span>  Host address: YOUR-SERVER-IP:xxx</span></span>
<span class="line"><span>  Local listen: 127.0.0.1:25565</span></span>
<span class="line"><span>  Punching through NAT ...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&gt;&gt;&gt; P2P direct link established with YOUR-SERVER-IP:xxx   ← punch succeeded!</span></span></code></pre></div><p>Now connecting to <code>127.0.0.1:25565</code> on the friend&#39;s machine reaches the host&#39;s <code>127.0.0.1:25565</code>.</p><p>If punching fails, it falls back automatically:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&gt;&gt;&gt; UDP hole punching failed, falling back to relay ...</span></span>
<span class="line"><span>&gt;&gt;&gt; relay connected, waiting for host ...</span></span></code></pre></div><p>The tunnel still works — traffic just goes through the server (see <a href="./architecture">Architecture</a>).</p><p>After a drop (network jitter, expired NAT mappings), both sides reconnect automatically:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&gt;&gt;&gt; 连接已断开，2 秒后自动重连（Ctrl-C 退出）...</span></span></code></pre></div><p>No manual action needed; the retry backoff is 2s, 4s, 8s... capped at 15s.</p><h2 id="minimal-commands" tabindex="-1">Minimal Commands <a class="header-anchor" href="#minimal-commands" aria-label="Permalink to &quot;Minimal Commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>Minimal command</th><th>Notes</th></tr></thead><tbody><tr><td>Host</td><td><code>frp-sh game create</code></td><td>every option has a default</td></tr><tr><td>Guest</td><td><code>frp-sh game join game-xxxxxx</code></td><td>only the room code is required</td></tr><tr><td>Server</td><td><code>frp-sh serve</code></td><td>listens on 0.0.0.0:8080/8081</td></tr></tbody></table><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="./cli">CLI Reference</a> for all options</li><li><a href="./advanced">Advanced Usage</a> for encryption, multi-connection, etc.</li><li><a href="./faq">Troubleshooting FAQ</a> if you hit problems</li></ul>`,37)])])}const k=e(n,[["render",l]]);export{g as __pageData,k as default};
